#include <queue>
#include <vector>
#include <deque>
#include <functional>

int main() {
    // 1. Default (Vector, Max-Heap)
    std::priority_queue<int> pq1; 

    // 2. Explicitly specifying std::vector (Max-Heap)
    std::priority_queue<int, std::vector<int>, std::less<int>> pq2;

    // 3. Using std::deque as the underlying container (Min-Heap)
    // Note: All three template arguments must be specified to change the container.
    std::priority_queue<int, std::deque<int>, std::greater<int>> pq3;

    pq3.push(5); pq3.push(1);
    // Underlying operations use deque's push_back/pop_back 
    // and random access indexing for heap maintenance.
}
